import zipfile
import xml.etree.ElementTree as ET
import re
import sys

NS = {'m': 'http://schemas.openxmlformats.org/officeDocument/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

def col_to_idx(ref):
    letters = re.match(r'[A-Z]+', ref).group(0)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx

def row_of(ref):
    return int(re.search(r'\d+', ref).group(0))

path = 'budget.xlsx'
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("Archive contents:", names)

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/officeDocument/2006/main}t'))
            shared.append(text)

    # workbook -> sheets and rels
    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels_root.findall('{http://schemas.openxmlformats.org/package/2006/relationships}Relationship'):
        rel_map[rel.get('Id')] = rel.get('Target')

    sheets = []
    for sh in wb_root.find('m:sheets', NS):
        rid = sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        sheets.append((sh.get('name'), rel_map.get(rid)))

    for sname, target in sheets:
        print(f"\n=== Sheet: {sname} ===")
        if target.startswith('/'):
            target = target[1:]
        else:
            target = 'xl/' + target
        root = ET.fromstring(z.read(target))
        rows = {}
        for c in root.iter('{http://schemas.openxmlformats.org/officeDocument/2006/main}c'):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            val = None
            if v is not None:
                val = v.text
                if t == 's':
                    val = shared[int(val)]
                elif t == 'b':
                    val = val == '1'
                elif t == 'str' or t == 'inlineStr':
                    val = val
                else:
                    try:
                        val = float(val)
                        if val.is_integer():
                            val = int(val)
                    except (ValueError, TypeError):
                        pass
            if val is not None:
                rows.setdefault(row_of(ref), {})[col_to_idx(ref)] = val
        for r in sorted(rows):
            row = rows[r]
            print(r, [row.get(c) for c in sorted(row)])

